namespace Necromancer.Core
{
    /// <summary>
    /// Статы игрока (героя). Единственный экземпляр на сцене через GameManager.
    /// </summary>
    public class PlayerStats : MonoBehaviour
    {
        [Header("Базовые")]
        public int level = 1;
        public int experience;
        public int experienceToNext = 100;

        [Header("Здоровье и мана")]
        public int maxHealth = 100;
        public int currentHealth;
        public int maxMana = 50;
        public int currentMana;
        public float manaRegenPerSecond = 5f;

        [Header("Боевые")]
        public int strength;
        public int intellect;
        public int stamina;
        public int minionControlLimit = 5; // Контроль нежити
        public float attackSpeed = 1f;
        public float criticalChance = 0.05f;
        public float criticalDamage = 1.5f;
        public int defense;
        public int resistance;

        [Header("Ресурсы")]
        public long souls;
        public long gold;
        public long darkCrystals;
        public long systemShards;
        public long catastropheEssence;

        [Header("Шкала Катастрофы")]
        public float catastropheFill; // 0..1
        public bool catastropheActive;

        public event System.Action<int, int> OnHealthChanged;
        public event System.Action<int, int> OnManaChanged;
        public event System.Action<long> OnSoulsChanged;
        public event System.Action<float> OnCatastropheFillChanged;

        void Awake()
        {
            currentHealth = maxHealth;
            currentMana = maxMana;
        }

        void Update()
        {
            if (!catastropheActive)
            {
                currentMana = Mathf.Min(maxMana, currentMana + Mathf.RoundToInt(manaRegenPerSecond * Time.deltaTime));
                OnManaChanged?.Invoke(currentMana, maxMana);
            }
        }

        public void Heal(int amount)
        {
            currentHealth = Mathf.Min(maxHealth, currentHealth + amount);
            OnHealthChanged?.Invoke(currentHealth, maxHealth);
        }

        public void TakeDamage(int amount)
        {
            int final = Mathf.Max(1, amount - defense);
            currentHealth = Mathf.Max(0, currentHealth - final);
            OnHealthChanged?.Invoke(currentHealth, maxHealth);

            // Катастрофа заполняется от урона
            AddCatastropheFill(0.02f);

            if (currentHealth <= 0)
            {
                currentHealth = 0;
                EventBus.Publish(new PlayerDiedMsg());
            }
        }

        public void AddSouls(int amount)
        {
            souls += amount;
            OnSoulsChanged?.Invoke(souls);
            AddCatastropheFill(0.01f * amount);
        }

        public void SpendSouls(int amount)
        {
            if (souls >= amount)
            {
                souls -= amount;
                OnSoulsChanged?.Invoke(souls);
            }
        }

        public bool CanAffordSouls(int amount) => souls >= amount;
        public bool CanAffordMana(int amount) => currentMana >= amount;
        public void SpendMana(int amount) => currentMana = Mathf.Max(0, currentMana - amount);

        public void AddCatastropheFill(float amount)
        {
            if (catastropheActive) return;
            catastropheFill = Mathf.Clamp01(catastropheFill + amount);
            OnCatastropheFillChanged?.Invoke(catastropheFill);

            if (catastropheFill >= 1f)
            {
                catastropheFill = 1f;
                EventBus.Publish(new CatastropheFillChangedMsg { FillNormalized = 1f, ReachedMax = true });
            }
            else
            {
                EventBus.Publish(new CatastropheFillChangedMsg { FillNormalized = catastropheFill, ReachedMax = false });
            }
        }

        public void SetCatastropheActive(bool active)
        {
            catastropheActive = active;
            if (!active)
                catastropheFill = 0f;
            EventBus.Publish(new CatastropheActivatedMsg { Active = active });
            EventBus.Publish(new CatastropheFillChangedMsg { FillNormalized = catastropheFill, ReachedMax = active });
        }
    }
}

using UnityEngine;

namespace Necromancer.Core
{
    /// <summary>
    /// Боевой компонент героя. Автоатака ближайшего врага + навыки через NecromancerController.
    /// </summary>
    [RequireComponent(typeof(PlayerStats))]
    public class PlayerCombat : MonoBehaviour
    {
        private PlayerStats stats;
        private Transform currentTarget;
        private float attackTimer;

        [Header("Визуал прототипа")]
        public SpriteRenderer spriteRenderer;
        public Color heroColor = new Color(0.6f, 0.8f, 1f, 1f); // Голубой неон

        void Awake()
        {
            stats = GetComponent<PlayerStats>();
            if (spriteRenderer != null)
                spriteRenderer.color = heroColor;
        }

        void Update()
        {
            if (stats.catastropheActive)
            {
                // В режиме Катастрофы герой наносит массовый урон continually
                return;
            }

            attackTimer += Time.deltaTime;
            float interval = 1f / stats.attackSpeed;

            if (currentTarget == null || !currentTarget.gameObject.activeInHierarchy)
            {
                currentTarget = FindNearestEnemy();
            }

            if (currentTarget != null && attackTimer >= interval)
            {
                attackTimer = 0f;
                Attack();
            }
        }

        private Transform FindNearestEnemy()
        {
            var enemies = FindObjectsOfType<EnemyInstance>();
            Transform nearest = null;
            float minDist = float.MaxValue;

            foreach (var e in enemies)
            {
                if (!e.isAlive) continue;
                float d = Vector2.Distance(transform.position, e.transform.position);
                if (d < minDist)
                {
                    minDist = d;
                    nearest = e.transform;
                }
            }
            return nearest;
        }

        private void Attack()
        {
            if (currentTarget == null) return;

            var enemy = currentTarget.GetComponent<EnemyInstance>();
            if (enemy != null)
            {
                int damage = Mathf.RoundToInt(10f + stats.strength * 2f);
                enemy.TakeDamage(damage);
            }
        }

        public void TakeDamage(int amount) => stats.TakeDamage(amount);

        public Transform GetCurrentTarget() => currentTarget;
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace Necromancer.Necromancy
{
    /// <summary>
    /// Управляет призывом нежити, навыками героя и армией 미ньонов.
    /// Вешается на героя (Player).
    /// </summary>
    public class NecromancerController : MonoBehaviour
    {
        public static NecromancerController Instance { get; private set; }

        [Header("Ссылки")]
        public PlayerStats stats;
        public PlayerCombat combat;

        [Header("Армия")]
        public List<MinionInstance> activeMinions = new List<MinionInstance>();
        public int maxMinions => stats.minionControlLimit;

        [Header("Навыки (Data)")]
        public SkillData[] allSkills;
        public int[] skillLevels; // Parallel to allSkills

        void Awake()
        {
            Instance = this;
            if (stats == null) stats = GetComponent<PlayerStats>();
            if (combat == null) combat = GetComponent<PlayerCombat>();

            // Инициализация уровней навыков (4 доступны со старта)
            skillLevels = new int[allSkills.Length];
            for (int i = 0; i < allSkills.Length; i++)
                skillLevels[i] = (i < 4) ? 1 : 0;
        }

        void Update()
        {
            // Очистка мёртвых из списка
            activeMinions.RemoveAll(m => m == null || !m.isAlive);
        }

        #region Призыв

        public bool TrySummonMinion(MinionData minionData)
        {
            if (activeMinions.Count >= maxMinions)
            {
                Debug.Log("[Necromancer] Лимит армии reached");
                return false;
            }
            if (!stats.CanAffordSouls(minionData.soulCost))
            {
                Debug.Log("[Necromancer] Недостаточно душ");
                return false;
            }
            if (level < minionData.requiredHeroLevel) return false;

            stats.SpendSouls(minionData.soulCost);
            var minion = MinionSpawner.Instance.Spawn(minionData, transform.position + Random.insideUnitCircle * 1.5f);
            if (minion != null)
            {
                activeMinions.Add(minion);
                EventBus.Publish(new Core.MinionSpawnedMsg { Minion = minion });
                return true;
            }
            return false;
        }

        public int level => stats.level;

        #endregion

        #region Навыки

        public bool TryUseSkill(int index)
        {
            if (index < 0 || index >= allSkills.Length) return false;
            var data = allSkills[index];
            int lvl = skillLevels[index];
            if (lvl == 0) return false; // Не разблокирован

            if (!stats.CanAffordMana(data.manaCost)) return false;

            float cd = data.GetCooldown(lvl);
            // Проверка КД упрощена — можно добавить массив timers
            stats.SpendMana(data.manaCost);
            ExecuteSkill(data, lvl);
            EventBus.Publish(new Core.SkillUsedMsg { SkillId = data.skillId });
            return true;
        }

        private void ExecuteSkill(SkillData data, int level)
        {
            int damage = Mathf.RoundToInt(data.baseDamage + data.damagePerLevel * (level - 1));
            switch (data.type)
            {
                case SkillType.Summon:
                    // Поднять скелета — призывает базового миньона (первый в списке данных можно захардкодить через кнопку UI)
                    Debug.Log($"[Skill] {data.displayName}: призыв скелета, урон {damage}");
                    break;
                case SkillType.AoE:
                    ApplyAoE(damage, data.radius);
                    break;
                case SkillType.Debuff:
                    ApplyFear(data.radius, data.durationSeconds);
                    break;
                case SkillType.Ultimate:
                    ActivateCatastrophe();
                    break;
                default:
                    Debug.Log($"[Skill] {data.displayName} использован, урон {damage}");
                    break;
            }
        }

        private void ApplyAoE(int damage, float radius)
        {
            var enemies = FindObjectsOfType<EnemyInstance>();
            foreach (var e in enemies)
            {
                if (!e.isAlive) continue;
                if (Vector2.Distance(transform.position, e.transform.position) <= radius)
                    e.TakeDamage(damage);
            }
            // Визуал можно добавить через VFX
        }

        private void ApplyFear(float radius, float duration)
        {
            var enemies = FindObjectsOfType<EnemyInstance>();
            foreach (var e in enemies)
            {
                if (!e.isAlive) continue;
                if (Vector2.Distance(transform.position, e.transform.position) <= radius)
                {
                    // Просто замедляем (упрощение)
                    e.moveSpeed *= 0.5f;
                }
            }
        }

        private void ActivateCatastrophe()
        {
            stats.SetCatastropheActive(true);
            // Экран темнеет, урон армии ×2, массовый урон врагам
            ApplyAoE(Mathf.RoundToInt(200f + stats.intellect * 5f), 12f);
            foreach (var m in activeMinions)
            {
                if (m != null && m.isAlive)
                    m.attackSpeed *= 2f;
            }
            // Автодеактивация через 8 секунд (упрощение — корутину лучше)
            StartCoroutine(DeactivateCatastropheAfter(8f));
        }

        private System.Collections.IEnumerator DeactivateCatastropheAfter(float seconds)
        {
            yield return new WaitForSeconds(seconds);
            stats.SetCatastropheActive(false);
            foreach (var m in activeMinions)
            {
                if (m != null && m.isAlive)
                    m.attackSpeed /= 2f;
            }
        }

        public void LevelUpSkill(int index)
        {
            if (index < 0 || index >= allSkills.Length) return;
            if (skillLevels[index] >= allSkills[index].maxLevel) return;
            skillLevels[index]++;
