            if (defeatPanel != null) defeatPanel.SetActive(true);
            Time.timeScale = 0f;
        }

        public void OpenMainMenu()
        {
            if (mainMenuPanel != null) mainMenuPanel.SetActive(true);
            if (hudPanel != null) hudPanel.SetActive(false);
            if (victoryPanel != null) victoryPanel.SetActive(false);
            if (defeatPanel != null) defeatPanel.SetActive(false);
            Time.timeScale = 1f;
        }

        public void StartBattleUI()
        {
            if (mainMenuPanel != null) mainMenuPanel.SetActive(false);
            if (hudPanel != null) hudPanel.SetActive(true);
            Time.timeScale = 1f;
        }

        public void SetSkillButton(int index, Data.SkillData data, int level)
        {
            if (index < 0 || index >= skillButtons.Length) return;
            skillButtons[index].Setup(data, level);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

namespace Necromancer.UI
{
    /// <summary>
    /// Кнопка навыка на боевом экране. Тап = использование навыка.
    /// </summary>
    public class SkillButton : MonoBehaviour
    {
        public int skillIndex;
        private Data.SkillData data;
        private int level;

        [Header("UI")]
        public Button button;
        public Image iconImage;
        public TextMeshProUGUI cooldownText;
        public TextMeshProUGUI manaCostText;
        public Image cooldownFill;

        private float cooldownTimer;

        public void Setup(Data.SkillData skillData, int lvl)
        {
            data = skillData;
            level = lvl;

            if (button != null)
            {
                button.onClick.RemoveAllListeners();
                button.onClick.AddListener(OnClick);
            }

            if (manaCostText != null)
                manaCostText.text = data.manaCost.ToString();

            UpdateVisuals();
        }

        private void OnClick()
        {
            if (cooldownTimer > 0f) return;

            var necro = Necromancy.NecromancerController.Instance;
            if (necro != null && necro.TryUseSkill(skillIndex))
            {
                cooldownTimer = data.GetCooldown(level);
                UpdateVisuals();
            }
        }

        void Update()
        {
            if (cooldownTimer > 0f)
            {
                cooldownTimer -= Time.deltaTime;
                if (cooldownTimer < 0f) cooldownTimer = 0f;
                UpdateVisuals();
            }
        }

        private void UpdateVisuals()
        {
            if (cooldownFill != null)
                cooldownFill.fillAmount = cooldownTimer > 0 ? cooldownTimer / data.GetCooldown(level) : 0f;

            if (cooldownText != null)
                cooldownText.text = cooldownTimer > 0 ? Mathf.CeilToInt(cooldownTimer).ToString() : "";

            var stats = GameManager.Instance.playerStats;
            bool canCast = stats != null && stats.currentMana >= data.manaCost && cooldownTimer <= 0;
            if (button != null)
                button.interactable = canCast && level > 0;

            var img = button.GetComponent<Image>();
            if (img != null)
                img.color = canCast ? Color.white : new Color(0.4f, 0.4f, 0.4f, 0.7f);
        }
    }
}

using UnityEngine;

namespace Necromancer.Input
{
    /// <summary>
    /// Обработка касаний для управления одной рукой (вертикальная ориентация).
    /// В прототипе кнопки навыков обрабатываются через Unity UI (OnClick).
    /// Этот скрипт может использоваться для жестов: тап по экрану = автофокус цели.
    /// </summary>
    public class TouchInputController : MonoBehaviour
    {
        void Update()
        {
            if (Input.touchCount > 0)
            {
                var touch = Input.GetTouch(0);
                if (touch.phase == TouchPhase.Began)
                {
                    // Если не нажали по UI, можно применить логику касания
                    if (!UnityEngine.EventSystems.EventSystem.current.IsPointerOverGameObject(touch.fingerId))
                    {
                        // Например, фокус атаки героя по точке касания
                        HandleGameplayTouch(touch.position);
                    }
                }
            }

            // ПК-эмуляция
            if (Input.GetMouseButtonDown(0))
            {
                if (!UnityEngine.EventSystems.EventSystem.current.IsPointerOverGameObject())
                    HandleGameplayTouch(Input.mousePosition);
            }
        }

        private void HandleGameplayTouch(Vector2 screenPos)
        {
            var ray = Camera.main.ScreenPointToRay(screenPos);
            if (Physics2D.Raycast(ray.origin, ray.direction))
            {
                // Можно бросить луч к врагу для фокуса
                Debug.Log("[Touch] Касание по миру");
            }
        }
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;

namespace Necromancer.Core
{
    /// <summary>
    /// Вешается на объект в сцене Battle. Привязывает ссылки GameManager к игроку,
    /// находит UIManager и запускает первый этап.
    /// </summary>
    public class BattleBootstrap : MonoBehaviour
    {
        [Header("Уровень")]
        public Data.LevelData levelToLoad;

        void Awake()
        {
            // Связь GameManager (DontDestroyOnLoad) с игрой на этой сцене
            var gm = GameManager.Instance;

            // Находим игрока на сцене
            var player = FindObjectOfType<PlayerCombat>();
            if (player != null)
            {
                gm.playerTransform = player.transform;
                gm.playerStats = player.GetComponent<PlayerStats>();
                gm.playerCombat = player;
                gm.necromancer = player.GetComponent<Necromancy.NecromancerController>();
            }

            // Инициализируем UI
            var ui = FindObjectOfType<UIManager>();
            if (ui != null)
                ui.StartBattleUI();

            // Подключаем навыки к кнопкам (пример: первые 4 навыка из контроллера)
            if (gm.necromancer != null && ui != null && gm.necromancer.allSkills.Length > 0)
            {
                for (int i = 0; i < Mathf.Min(ui.skillButtons.Length, gm.necromancer.allSkills.Length); i++)
                {
                    ui.SetSkillButton(i, gm.necromancer.allSkills[i], gm.necromancer.skillLevels[i]);
                }
            }
        }

        void Start()
        {
            // Автостарт боя, если передан уровень
            if (levelToLoad != null && BattleManager.Instance != null)
                BattleManager.Instance.StartBattle(levelToLoad);
        }
    }
}

